-- Standalone: Gateway (race 2) predictions + feature importances.
-- Safe to re-run; replaces any existing Gateway rows.
begin;
update races set blend_note = '70% flat-mile season form / 30% Gateway Chase history' where chase_round = 2;

delete from predictions where race_id = (select id from races where chase_round = 2);
delete from feature_importances where race_id = (select id from races where chase_round = 2);


commit;
